import java.util.Scanner;

public class Main {
    static long p_value, k_value;
    static long[] visited_nodes = new long[1000006];
    static long total_cycles;

    static long compute_power(long base, long exp) {
        long result = 1;
        for (int i = 30; i >= 0; i--) {
            result = (result * result) % 1000000007;
            if (((long)1 << i & exp) != 0) {
                result = (result * base) % 1000000007;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_cycles = 0;
        p_value = sc.nextLong();
        k_value = sc.nextLong();

        if (k_value == 1) {
            System.out.println(compute_power(p_value, p_value));
            sc.close();
            return;
        }

        for (int i = 1; i < p_value; i++) {
            if (visited_nodes[i] == 0) {
                visited_nodes[i] = 1;
                total_cycles++;
                long current_node = (i * k_value) % p_value;
                while (visited_nodes[(int)current_node] == 0) {
                    visited_nodes[(int)current_node] = 1;
                    current_node = (current_node * k_value) % p_value;
                }
            }
        }
        System.out.println(compute_power(p_value, total_cycles));
        sc.close();
    }
}
